import{_ as i,c as a,o,j as n,Y as r,t as s}from"./chunks/framework.BNTND4LZ.js";const m=JSON.parse('{"title":"git-multi-pack-index | x-cmd man (git man1) | Write and verify multi-pack-indexes","titleTemplate":false,"description":"x-cmd man (git man1 Manual Page) | git-multi-pack-index - Write and verify multi-pack-indexes","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"git-multi-pack-index | x-cmd man (git man1) | Write and verify multi-pack-indexes"}],["meta",{"name":"og:description","content":"x-cmd man (git man1 Manual Page) | git-multi-pack-index - Write and verify multi-pack-indexes"}]]},"headers":[],"params":{"isMan":true,"man":"git-multi-pack-index","category":"git man1","desc":"Write and verify multi-pack-indexes"},"relativePath":"git/man1/git-multi-pack-index.md","filePath":"git/man1/[man].md"}'),c={name:"git/man1/git-multi-pack-index.md"},p={class:"visually-hidden"};function l(t,e,d,h,k,g){return o(),a("div",null,[n("h1",p,s(t.$params.man),1),e[0]||(e[0]=r(`<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>git-multi-pack-index - Write and verify multi-pack-indexes</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> multi-pack-index</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--object-dir=&lt;dir&gt;] [--[no-]bitmap] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sub-command</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>Write or verify a multi-pack-index (MIDX) file.</p><h2 id="options" tabindex="-1">OPTIONS <a class="header-anchor" href="#options" aria-label="Permalink to &quot;OPTIONS&quot;">​</a></h2><p>--object-dir=&lt;dir&gt;</p><blockquote><p>Use given directory for the location of Git objects. We check <strong>&lt;dir&gt;/packs/multi-pack-index</strong> for the current MIDX file, and <strong>&lt;dir&gt;/packs</strong> for the pack-files to index.</p><p><strong>&lt;dir&gt;</strong> must be an alternate of the current repository.</p></blockquote><p>--[no-]progress</p><blockquote><p>Turn progress on/off explicitly. If neither is specified, progress is shown if standard error is connected to a terminal. Supported by sub-commands <strong>write</strong>, <strong>verify</strong>, <strong>expire</strong>, and \`repack.</p></blockquote><p>The following subcommands are available:</p><p>write</p><blockquote><p>Write a new MIDX file. The following options are available for the <strong>write</strong> sub-command:</p><p>--preferred-pack=&lt;pack&gt;</p><blockquote><p>Optionally specify the tie-breaking pack used when multiple packs contain the same object. <strong>&lt;pack&gt;</strong> must contain at least one object. If not given, ties are broken in favor of the pack with the lowest mtime.</p></blockquote><p>--[no-]bitmap</p><blockquote><p>Control whether or not a multi-pack bitmap is written.</p></blockquote><p>--stdin-packs</p><blockquote><p>Write a multi-pack index containing only the set of line-delimited pack index basenames provided over stdin.</p></blockquote><p>--refs-snapshot=&lt;path&gt;</p><blockquote><p>With <strong>--bitmap</strong>, optionally specify a file which contains a &quot;refs snapshot&quot; taken prior to repacking.</p><p>A reference snapshot is composed of line-delimited OIDs corresponding to the reference tips, usually taken by <strong>git repack</strong> prior to generating a new pack. A line may optionally start with a <strong>+</strong> character to indicate that the reference which corresponds to that OID is &quot;preferred&quot; (see <strong>git-config</strong>(1)&#39;s <strong>pack.preferBitmapTips</strong>.)</p><p>The file given at <strong>&lt;path&gt;</strong> is expected to be readable, and can contain duplicates. (If a given OID is given more than once, it is marked as preferred if at least one instance of it begins with the special <strong>+</strong> marker).</p></blockquote></blockquote><p>verify</p><blockquote><p>Verify the contents of the MIDX file.</p></blockquote><p>expire</p><blockquote><p>Delete the pack-files that are tracked by the MIDX file, but have no objects referenced by the MIDX (with the exception of <strong>.keep</strong> packs and cruft packs). Rewrite the MIDX file afterward to remove all references to these pack-files.</p></blockquote><p>repack</p><blockquote><p>Create a new pack-file containing objects in small pack-files referenced by the multi-pack-index. If the size given by the <strong>--batch-size=&lt;size&gt;</strong> argument is zero, then create a pack containing all objects referenced by the multi-pack-index. For a non-zero batch size, Select the pack-files by examining packs from oldest-to-newest, computing the &quot;expected size&quot; by counting the number of objects in the pack referenced by the multi-pack-index, then divide by the total number of objects in the pack and multiply by the pack size. We select packs with expected size below the batch size until the set of packs have total expected size at least the batch size, or all pack-files are considered. If only one pack-file is selected, then do nothing. If a new pack-file is created, rewrite the multi-pack-index to reference the new pack-file. A later run of <em>git multi-pack-index expire</em> will delete the pack-files that were part of this batch.</p><p>If <strong>repack.packKeptObjects</strong> is <strong>false</strong>, then any pack-files with an associated <strong>.keep</strong> file will not be selected for the batch to repack.</p></blockquote><h2 id="examples" tabindex="-1">EXAMPLES <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;EXAMPLES&quot;">​</a></h2><blockquote><p>·</p><p>Write a MIDX file for the packfiles in the current <strong>.git</strong> directory.</p><blockquote><pre><code>$ git multi-pack-index write
</code></pre></blockquote></blockquote><blockquote><p>·</p><p>Write a MIDX file for the packfiles in the current <strong>.git</strong> directory with a corresponding bitmap.</p><blockquote><pre><code>$ git multi-pack-index write --preferred-pack=&lt;pack&gt; --bitmap
</code></pre></blockquote></blockquote><blockquote><p>·</p><p>Write a MIDX file for the packfiles in an alternate object store.</p><blockquote><pre><code>$ git multi-pack-index --object-dir &lt;alt&gt; write
</code></pre></blockquote></blockquote><blockquote><p>·</p><p>Verify the MIDX file for the packfiles in the current <strong>.git</strong> directory.</p><blockquote><pre><code>$ git multi-pack-index verify
</code></pre></blockquote></blockquote><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p>See <strong>The Multi-Pack-Index Design Document</strong>[1] and <strong>gitformat-pack</strong>(5) for more information on the multi-pack-index feature and its file format.</p><h2 id="git" tabindex="-1">GIT <a class="header-anchor" href="#git" aria-label="Permalink to &quot;GIT&quot;">​</a></h2><p>Part of the <strong>git</strong>(1) suite</p><h2 id="notes" tabindex="-1">NOTES <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;NOTES&quot;">​</a></h2><ol><li></li></ol><p>: The Multi-Pack-Index Design Document</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">file:///usr/share/doc/git/technical/multi-pack-index.html</span></span></code></pre></div>`,33))])}const f=i(c,[["render",l]]);export{m as __pageData,f as default};
